function formatLcoDuration(ms){if(ms<=0)return '0s';var s=Math.floor(ms/1000);var m=Math.floor(s/60);var h=Math.floor(m/60);var d=Math.floor(h/24);if(d>0)return d+'d '+(h%24)+'h';if(h>0)return h+'h '+(m%60)+'m';if(m>0)return m+'m '+(s%60)+'s';return s+'s';}
