function playBeep(f,d,t){if(!_soundEnabled)return;if(currentUser&&currentUser.soundEnabled===false)return;initAudio();if(!_audioCtx)return;try{var o=_audioCtx.createOscillator();var g=_audioCtx.createGain();o.type=t||'sine';o.frequency.value=f;g.gain.setValueAtTime(0.08,_audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(0.001,_audioCtx.currentTime+d);o.connect(g);g.connect(_audioCtx.destination);o.start();o.stop(_audioCtx.currentTime+d);}catch(e){}}
