function triggerReleaseSequence(){var t=document.getElementById('pageTitle');if(t)t.innerText="Crystal Collecting Simulator";var game=ROBLOX_GAMES.crystal;var custom=getCustomCrystalItems();var html='<div style="margin-bottom:20px"><a href="'+game.url+'" target="_blank" rel="noopener" class="roblox-btn">🎮 Play on Roblox</a></div>';html+='<div style="text-align:center;padding:40px 30px;background:linear-gradient(135deg,#e0f2fe,#fff);border:2px solid #0ea5e9;border-radius:12px;margin-bottom:20px"><div style="font-size:5rem">💎</div><h2 style="margin-top:0;color:#0ea5e9;border:none">Game Announcement</h2><p style="font-weight:bold;color:#075985;font-size:1.2rem">Crystal Collecting Simulator</p><p><b>Releases September 28, 2026 at 1:00 PM!</b></p><div style="margin-top:25px"><a href="'+game.url+'" target="_blank" rel="noopener" class="roblox-btn">🔔 Wishlist / Play</a></div></div>';if(custom&&custom.length>0){html+='<h2>Crystal Items</h2><table class="wikitable"><tr><th>#</th><th>Name</th><th>Cost</th><th>Health</th><th>Duration</th><th>Rarity</th></tr>';custom.forEach(function(it,i){html+='<tr><td>'+(i+1)+'</td><td><b>'+escapeHtml(it.name)+'</b></td><td>'+(it.cost||0).toLocaleString()+'</td><td>'+(it.health||0).toLocaleString()+'</td><td>'+escapeHtml(it.duration||'-')+'</td><td>'+escapeHtml(it.rarity||'-')+'</td></tr>';});html+='</table>';}var c=document.getElementById('pageContent');if(c)c.innerHTML=html;}
function openPolicy(){var t=document.getElementById('pageTitle');if(t)t.innerText='Terms of Policy';var rules=["Users must be 13 years or older.","Do not copy or redistribute this website.","Do not reveal sensitive credentials.","Give proper credit to Dev Xdragon and LumeCraftor.","Respect all community members.","No cheating, exploiting, or hacking.","No bots or auto-clickers.","Multiple accounts for referrals will be banned.","Daily Rewards once per 24 hours.","Cash out must be legitimate.","Minimum cash out ₱3.00.","VIP/Premium non-refundable.","Custom backgrounds must not be NSFW.","Max 2MB upload.","False reports = 1,500 Coin penalty.","Abuser reports need valid Roblox ID.","Do not impersonate staff.","Poll votes once per hour.","All activity logged to Firebase.","Data never shared with third parties.","Features may change without notice.","Breaking rules = ban.","Appeals via Facebook/Discord.","Continued use = acceptance of all policies.","Thank you for supporting RedGalaxy Studio!"];var rh=rules.map(function(r,i){return '<li><b>Rule '+(i+1)+':</b> '+r+'</li>';}).join('');var c=document.getElementById('pageContent');if(c)c.innerHTML='<div class="policy-card"><h2 style="margin-top:0;color:#005a9c;border-bottom:2px solid #3366cc;padding-bottom:8px">[XDRG Studio — Terms of Policy]</h2><ol class="policy-list">'+rh+'</ol><div style="margin-top:20px"><a onclick="openHome()" class="policy-back-btn">I have read and accept all policies</a></div></div>';}
function openBuyPasses(){var t=document.getElementById('pageTitle');if(t)t.innerText='🎟️ Buy Passes';var vb=(currentUser&&currentUser.isVIP)?'<button class="btn-claim" style="width:100%;background:#6c757d;cursor:not-allowed" disabled>Already Bought!</button>':'<button class="btn-claim" style="width:100%" onclick="purchasePass(\'VIP\')">Buy VIP Pass</button>';var pb=(currentUser&&currentUser.isPremium)?'<button class="btn-claim" style="width:100%;background:#6c757d;cursor:not-allowed" disabled>Already Bought!</button>':'<button class="btn-claim" style="width:100%;background:#00c6ff" onclick="purchasePass(\'Premium\')">Buy Premium Pass</button>';var c=document.getElementById('pageContent');if(c)c.innerHTML='<div style="max-width:800px;margin:0 auto"><h2>Unlock Exclusive Perks!</h2><div style="display:flex;gap:20px;flex-wrap:wrap;margin-top:30px"><div style="flex:1;min-width:300px;background:rgba(248,249,250,.95);border:2px solid #ffd700;border-radius:10px;padding:20px;text-align:center"><h3 style="color:#ffd700">⭐ VIP Pass</h3><div style="font-size:2rem;margin:15px 0">💰 12,500 Coins</div><ul style="text-align:left"><li>✅ VIP Badge & Backgrounds</li><li>✅ 50 min Cash Out</li><li>✅ Free 250 Coins</li></ul>'+vb+'</div><div style="flex:1;min-width:300px;background:rgba(248,249,250,.95);border:2px solid #00c6ff;border-radius:10px;padding:20px;text-align:center"><h3 style="color:#00c6ff">💎 Premium Pass</h3><div style="font-size:2rem;margin:15px 0">💰 25,000 Coins</div><ul style="text-align:left"><li>✅ Premium + VIP</li><li>✅ 15 min Cash Out</li><li>✅ Free 1,500 Coins</li><li>✅ -15 Reward Discount</li><li>✅ Free 2 In-Game Rewards</li></ul>'+pb+'</div></div></div>';}
async function purchasePass(pt){if(!currentUser)return;if(pt==='VIP'&&currentUser.isVIP){showToast("Already bought!","error");return;}if(pt==='Premium'&&currentUser.isPremium){showToast("Already bought!","error");return;}var cost=pt==='VIP'?12500:25000;if(!isOwnerAccount(currentUser)&&(currentUser.points||0)<cost){showToast("❌ Need "+cost.toLocaleString()+" Coins!","error");return;}if(!confirm("Buy "+pt+" for "+cost.toLocaleString()+" Coins?"))return;if(!isOwnerAccount(currentUser))currentUser.points-=cost;if(pt==='VIP'){currentUser.isVIP=true;currentUser.points+=250;showToast('🎉 VIP!','success');}else{currentUser.isPremium=true;currentUser.isVIP=true;currentUser.points+=1500;currentUser.premiumFreeClaims=(currentUser.premiumFreeClaims||0)+2;showToast('🎉 Premium!','success');}saveUserData();updateUserStatusHeader();openBuyPasses();sfxCoin();}
function openClaimsHistory(){var t=document.getElementById('pageTitle');if(t)t.innerText='📜 Claim Delivery History';var lc=safeGetJSON('user_claims_'+currentUser.rblxUserId,[]);var pb=currentUser.isHistoryPublic?'<span style="color:#0d9488;font-weight:bold;font-size:.85rem">[ Public ✅ ]</span>':'<span style="color:#c82333;font-weight:bold;font-size:.85rem">[ Private 🔒 ]</span>';var html='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:15px"><p style="color:#54595d;margin:0">Records for <b>'+escapeHtml(currentUser.displayName||currentUser.name)+'</b> '+pb+'</p><button onclick="openSettings()" class="btn-save" style="font-size:.8rem">Change Privacy</button></div><table class="wikitable"><tr><th>#</th><th>Item</th><th>Cost</th><th>Status</th><th>Time</th></tr>';if(lc.length===0)html+='<tr><td colspan="5" style="text-align:center;color:#777;padding:20px">No claims.</td></tr>';else lc.forEach(function(i,x){var st=(i.status||'pending').toLowerCase();var b='<span class="status-badge status-pending">⏳ Pending</span>';if(['successful','delivered','received'].indexOf(st)!==-1)b='<span class="status-badge status-successful">✅ Received</span>';else if(['unsuccessful','failed','rejected'].indexOf(st)!==-1)b='<span class="status-badge status-unsuccessful">❌ Failed</span>';html+='<tr><td>'+(x+1)+'</td><td><b>'+escapeHtml(i.reward||'?')+'</b></td><td>'+(i.cost===0?'FREE':(i.cost||35)+' Coins')+'</td><td>'+b+'</td><td>'+new Date(i.timestamp).toLocaleString()+'</td></tr>';});html+='</table>';var c=document.getElementById('pageContent');if(c)c.innerHTML=html;}
function openLeaderboard(){var t=document.getElementById('pageTitle');if(t)t.innerText='🏆 Leaderboard Statics';var au=safeGetJSON('app_users_db',[]);var bots=getBotUsers();au=au.concat(bots.filter(function(b){return b.points>0;}));au.sort(function(a,b){return (b.points||0)-(a.points||0);});var sym=getCurrencySymbol();var html='<p>Top players.</p><table class="leaderboard-table"><tr><th>Rank</th><th>Name</th><th>Coins</th><th>Cash</th></tr>';au.slice(0,20).forEach(function(u,i){html+='<tr><td style="font-weight:bold;color:#28a745;text-align:center">#'+(i+1)+'</td><td><b>'+escapeHtml(u.username||u.name||'?')+'</b>'+verifiedBadgeHtml(u)+'</td><td>'+(u.points||0).toLocaleString()+'</td><td>'+sym+((u.points||0)/10000).toFixed(2)+'</td></tr>';});html+='</table>';var c=document.getElementById('pageContent');if(c)c.innerHTML=html;}
function openSneakPeek(){var t=document.getElementById('pageTitle');if(t)t.innerText='👀 Sneak Peek';var c=document.getElementById('pageContent');if(c)c.innerHTML='<p>Latest from developers!</p><div id="sneakPeekGrid" class="sneak-grid"></div>';fetchSneakPeeks();}
async function fetchSneakPeeks(){try{var r=await fetch(FIREBASE_BASE_URL+'/sneak_peeks.json');if(r.ok){var d=await r.json();globalSneakPeeks=[];if(d)Object.keys(d).forEach(function(id){globalSneakPeeks.push(Object.assign({id:id},d[id]));});globalSneakPeeks.sort(function(a,b){return (b.timestamp||0)-(a.timestamp||0);});renderSneakPeekContent();}}catch(e){}}
function renderSneakPeekContent(){var g=document.getElementById('sneakPeekGrid');if(!g)return;if(globalSneakPeeks.length===0){g.innerHTML='<div style="padding:20px;color:#777">No sneaks yet.</div>';return;}g.innerHTML=globalSneakPeeks.map(function(p){return '<div class="sneak-card"><img src="'+escapeHtml(p.image||'')+'"><div class="sneak-card-content"><h4>'+escapeHtml(p.title)+'</h4><p>'+escapeHtml(p.description)+'</p><div style="font-size:.75rem;color:#888;font-style:italic">'+new Date(p.timestamp).toLocaleString()+' — @'+escapeHtml(p.uploader)+'</div></div></div>';}).join('');}
async function openQuests(){var t=document.getElementById('pageTitle');if(t)t.innerText='🎯 Quest and Trade Service';try{await syncRealtimeDatabase();}catch(e){}renderQuestsPage();}
async function renderQuestsPage(){if(!currentUser)return;var cd=getUserCoinsDisplay(currentUser);var cu=window.location.protocol+'//'+window.location.host+window.location.pathname;var ail=cu+'?ref='+currentUser.rblxUserId;var rs=safeGetJSON('referralDataStore',{});var di=rs[currentUser.rblxUserId]||0;var today=new Date().toDateString();var lc=currentUser.lastClaimedDate?new Date(currentUser.lastClaimedDate).toDateString():null;var canClaim=lc!==today;var st=currentUser.streakCount||0;if(canClaim&&lc){var y=new Date();y.setDate(y.getDate()-1);if(lc!==y.toDateString())st=0;}var dg='';[1,2,3,4,5,6,7].forEach(function(d){var isA=(d===st+1&&canClaim)?'active':'';var isC=(d<=st)?'claimed':'';var r=d===7?100:50;dg+='<div class="daily-card '+isA+' '+isC+'"><div class="day-label">Day '+d+'</div><div class="reward-icon">💰</div><div class="reward-amount">'+r+'</div></div>';});var drh='';if(canClaim){var nd=st+1;var rw=nd===7?100:50;drh='<div class="quest-box" style="border-color:#28a745;border-width:2px;background:linear-gradient(135deg,#f0fff4,#fff)"><h3 style="color:#28a745;margin-top:0">🎁 Daily Engagement Rewards</h3><div class="daily-grid">'+dg+'</div><button class="btn-claim" style="width:100%;margin-top:15px;font-size:1.15rem;padding:14px" onclick="claimDailyRewardAction()">🎁 Claim Day '+nd+' ('+rw+' Coins)</button></div>';}else{drh='<div class="quest-box" style="border-color:#6c757d;background:rgba(233,236,239,.9)"><h3 style="color:#6c757d;margin-top:0">🎁 Daily Rewards</h3><p>✅ Already claimed today.</p><div class="daily-grid">'+dg+'</div></div>';}var hFC=currentUser.premiumFreeClaims>0;var sC=hFC?0:(currentUser.isPremium?20:35);var lb='';if(globalLimitedCashOut&&globalLimitedCashOut.expiresAt>Date.now()){var rem=Math.max(0,globalLimitedCashOut.expiresAt-Date.now());lb='<div class="quest-box" style="background:linear-gradient(135deg,#ff6b6b,#feca57);border:none;color:#fff"><h3 style="margin-top:0;color:#fff">🤑 LIMITED CASH OUT!</h3><p>Get <b>₱'+globalLimitedCashOut.money+'</b> for <b>'+(globalLimitedCashOut.costCoins||20000).toLocaleString()+' Coins</b>!</p><p>⏳ <b id="lcoQuestTimer">'+formatLcoDuration(rem)+'</b></p><button class="btn-claim" style="width:100%;background:#fff;color:#dc3545" onclick="openCashOutPage()">💸 Redeem Now</button></div>';}var ab='';if(!isAgeVerified(currentUser)){ab='<div class="age-verify-banner"><h3>🪪 Verify your age before cash out!💰</h3><button onclick="openAgeUi(\'verify\')">📤 Verify Now</button></div>';}var html='<div class="points-header">Coins: <span id="pointCount">'+cd+'</span></div>'+ab+lb+drh;html+='<div class="quest-box"><h3>Quest 1: Invite Friend (+25 Points)</h3><div class="copy-container"><input type="text" id="inviteUrlInput" value="'+ail+'" readonly><button class="btn-copy" onclick="copyInviteLink()">Copy</button></div><div style="margin-top:12px;font-weight:bold;color:#005a9c">📊 Verified: '+di+'</div></div>';html+='<div class="quest-box"><h3>Quest 2: Emoji Puzzle (+1 Pt/Level)</h3><p>Level <span id="gameLevel">'+(currentUser.level||1)+'</span>/250</p><div class="game-grid" id="gameGrid"></div></div>';html+='<div class="quest-box"><h3>🎁 Select Trade Reward</h3>'+(currentUser.isPremium?'<div style="background:#e6fffa;padding:10px;border-radius:4px;margin-bottom:10px;font-size:.85rem;color:#0d9488">💎 Premium: 20 Coins!'+(hFC?'<br>🎁 '+currentUser.premiumFreeClaims+' Free!':'')+'</div>':'')+'<label><b>Choose Item:</b></label><select id="selectedRewardInput" class="reward-select"><option value="Strawberry Elephant">Strawberry Elephant ('+sC+' Coins)</option><option value="Summerini Fattini">Summerini Fattini ('+sC+' Coins)</option></select><button class="btn-claim" onclick="claimRewardFirebase()">Claim Item</button></div>';html+='<div class="quest-box" style="background:linear-gradient(135deg,#fce7f3,#fff)"><h3 style="color:#db2777">🖼️ XDRG Img Shot</h3><button class="btn-claim" style="width:100%;background:#ec4899" onclick="openVideoShares()">🖼️ Open</button></div>';html+='<div class="quest-box" style="background:linear-gradient(135deg,#fef3c7,#fff)"><h3 style="color:#b45309">🎰 Lucky Spin</h3><button class="btn-claim" style="width:100%;background:#f59e0b" onclick="openLuckySpin()">🎰 Open</button></div>';html+='<div class="quest-box" style="background:linear-gradient(135deg,#f3e8ff,#fff)"><h3 style="color:#8b5cf6">🛍️ XDRG Shop</h3><button class="btn-claim" style="width:100%;background:#8b5cf6" onclick="openXdrgShop()">🛍️ Open</button></div>';var ph='';if(globalPolls.length===0)ph='<div style="padding:15px;text-align:center;color:#777">No active polls.</div>';else{globalPolls.forEach(function(p){ph+='<div class="poll-card"><h4>'+escapeHtml(p.title)+'</h4>';if(p.image)ph+='<img src="'+escapeHtml(p.image)+'" style="max-width:300px;border-radius:6px">';if(p.description)ph+='<p>'+escapeHtml(p.description)+'</p>';(p.options||[]).forEach(function(o,i){ph+='<div style="display:flex;justify-content:space-between;padding:10px;background:#fff;border-radius:4px;border:1px solid #a2a9b1;margin-top:6px"><span><b>'+escapeHtml(o.name)+'</b> ('+(o.votes||0)+')</span><button class="btn-save" style="background:#005a9c" onclick="castVote(\''+p.id+'\','+i+')">Vote (+5)</button></div>';});});}html+='<div class="quest-box"><h3>Quest 3: Community Voting (+5 Points)</h3>'+ph+'</div>';var pc=document.getElementById('pageContent');if(pc)pc.innerHTML=html;initMiniGame();if(window._lcoQuestInt)clearInterval(window._lcoQuestInt);window._lcoQuestInt=setInterval(function(){var el=document.getElementById('lcoQuestTimer');if(!el){clearInterval(window._lcoQuestInt);window._lcoQuestInt=null;return;}if(!globalLimitedCashOut||globalLimitedCashOut.expiresAt<=Date.now()){clearInterval(window._lcoQuestInt);window._lcoQuestInt=null;return;}el.textContent=formatLcoDuration(globalLimitedCashOut.expiresAt-Date.now());},1000);}
function copyInviteLink(){var li=document.getElementById('inviteUrlInput');if(!li)return;li.select();li.setSelectionRange(0,99999);var done=function(){showToast('✅ Copied!','success');};var fail=function(){try{document.execCommand('copy');done();}catch(e){showToast('❌ Copy failed','error');}};if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(li.value).then(done,fail);}else{fail();}}
function initMiniGame(){var g=document.getElementById('gameGrid');if(!g)return;g.innerHTML='';selectedCards=[];var em=["🐱","🐶","🦊","🐸","🐵","🦁"];var re=em[Math.floor(Math.random()*em.length)];var cv=[re,re,'❓','❓'];cv.sort(function(){return Math.random()-0.5;});cv.forEach(function(v){var c=document.createElement('div');c.className='emoji-card';c.innerText='❓';c.dataset.value=v;c.onclick=function(){flipCard(c);};g.appendChild(c);});}
function flipCard(c){if(selectedCards.length<2&&c.innerText==='❓'){c.innerText=c.dataset.value;selectedCards.push(c);if(selectedCards.length===2)setTimeout(checkMatch,600);}}
function checkMatch(){var c1=selectedCards[0],c2=selectedCards[1];if(c1&&c2&&c1.dataset.value===c2.dataset.value&&c1.dataset.value!=='❓'){if(currentUser.level<=250){if(!isOwnerAccount(currentUser))currentUser.points=(currentUser.points||0)+1;currentUser.level=(currentUser.level||1)+1;saveUserData();var pc=document.getElementById('pointCount');if(pc)pc.innerText=getUserCoinsDisplay(currentUser);var gl=document.getElementById('gameLevel');if(gl)gl.innerText=currentUser.level;sfxCoin();}}initMiniGame();}
async function castVote(pid,oi){if(!currentUser)return;var now=Date.now();if(now-(currentUser.lastVoteTime||0)<3600000){showToast("⏳ Cooldown!","error");return;}var poll=null;for(var i=0;i<globalPolls.length;i++){if(globalPolls[i].id===pid){poll=globalPolls[i];break;}}if(!poll||!poll.options[oi])return;poll.options[oi].votes=(poll.options[oi].votes||0)+1;try{await fetch(FIREBASE_BASE_URL+'/polls/'+pid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(poll)});}catch(e){}currentUser.lastVoteTime=now;currentUser.points=(currentUser.points||0)+5;saveUserData();updateUserStatusHeader();showToast("✅ +5 Coins!","success");sfxCoin();renderQuestsPage();}
async function claimRewardFirebase(){var ri=document.getElementById('selectedRewardInput').value;var isOwner=isOwnerAccount(currentUser);var hFC=currentUser.premiumFreeClaims>0;var rc=35;if(currentUser.isPremium)rc=20;if(hFC&&!isOwner)rc=0;if(!isOwner&&(currentUser.points||0)<rc){showToast("⚠️ Need "+rc+" Coins!","error");return;}var cid="CLAIM-"+Date.now();var cd={id:cid,username:currentUser.username||currentUser.name,reward:ri,cost:isOwner?0:rc,email:currentUser.gmail,status:"pending",timestamp:Date.now()};var lc=safeGetJSON('user_claims_'+currentUser.rblxUserId,[]);lc.unshift(cd);try{localStorage.setItem('user_claims_'+currentUser.rblxUserId,JSON.stringify(lc));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/claims/'+cid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(cd)});}catch(e){}if(!isOwner){if(hFC){currentUser.premiumFreeClaims-=1;showToast("🎉 FREE! Remaining: "+currentUser.premiumFreeClaims,"success");}else{currentUser.points=Math.max(0,(currentUser.points||0)-rc);showToast("🎉 Submitted! Cost: "+rc,"success");}}else showToast("👑 FREE!","success");var rarMap={'Strawberry Elephant':'Limited','Summerini Fattini':'Godly'};addToInventory(ri,rarMap[ri]||'Common',{source:'quest'});saveUserData();openClaimsHistory();}
